// electron-builder beforePack hook — hard guards on generated assets.
//
// The sandbox stdlib prelude is generated by `scripts/generate-sandbox-prelude.mts`
// (hooked on prebuild / predist / prepackage) and shipped via extraResources.
// electron-builder only WARNS when an extraResources source is missing, which
// would silently ship a packaged app whose code nodes fall back to runtime
// bundling — impossible from inside app.asar. Fail the build loudly instead.
'use strict'

const { existsSync, statSync } = require('node:fs')
const { join } = require('node:path')

exports.default = async function beforePack() {
  const prelude = join(__dirname, '..', 'resources', 'sandbox-stdlib-prelude.js')
  if (!existsSync(prelude) || statSync(prelude).size < 100_000) {
    throw new Error(
      `sandbox stdlib prelude missing or truncated at ${prelude} — ` +
      'run `node scripts/generate-sandbox-prelude.mts` (hooked on prebuild/predist/prepackage)'
    )
  }
}
